using Pkg
Pkg.activate(joinpath(@__DIR__, "../../MoM_AllinOne"))

using MoM_AllinOne
using LinearAlgebra

function run_legacy_benchmark()
    println("==================================================")
    println("   Legacy Benchmark: PEC Plate RCS (EFIE)         ")
    println("==================================================")

    # Setup
    setPrecision!(Float64)
    SimulationParams.SHOWIMAGE = false

    # Parameters
    # Note: plate_benchmark.nas must be generated by benchmark_plate.jl first
    filename = joinpath(@__DIR__, "plate_benchmark.nas")
    if !isfile(filename)
        error("Mesh file $filename not found. Run benchmark_plate.jl first.")
    end
    
    meshUnit = :m
    frequency = 300e6
    
    ieT = :EFIE
    sbfT = :RWG
    vbfT = :nothing
    solverT = :gmres
    rtol = 1e-4
    restart = 1000

    # Source
    # Theta=0, Phi=0, E_theta=1, E_phi=0 (Approx x-pol if theta->0 limit handled)
    source = PlaneWave(0.0, 0.0, 1.0, 0.0)

    println("Running MoM_AllinOne Direct Solver (with GMRES)...")
    
    # We can't just include direct_solver.jl because it runs at top level.
    # We'll copy the relevant parts.
    
    # 1. Update Parameters
    inputParameters(;frequency = frequency, ieT = ieT)
    updateVSBFTParams!(;sbfT = sbfT, vbfT = vbfT)

    # 2. Read Mesh
    println("[1/4] Reading Mesh...")
    meshData, εᵣs = getMeshData(filename; meshUnit=meshUnit)
    
    # 3. Basis
    println("[2/4] Generating Basis...")
    t_basis = @elapsed begin
        ngeo, nbf, geosInfo, bfsInfo = getBFsFromMeshData(meshData; sbfT = sbfT, vbfT = vbfT)
    end
    println("      Basis setup in $t_basis s")
    println("      Unknowns: $nbf")

    # 4. Matrix Assembly
    println("[3/4] Assembling Matrix...")
    setGeosPermittivity!(geosInfo, 2(1-0.0002im)) # Default in example, maybe irrelevant for PEC?
    # For PEC, permittivity shouldn't matter if code handles it.
    # MoM_AllinOne might treat everything as dielectric if not specified?
    # Wait, EFIE usually implies PEC or dielectric surface.
    # Let's assume default handling is correct for the example.
    
    t_assembly = @elapsed begin
        Zmat = getImpedanceMatrix(geosInfo, nbf)
    end
    println("      Assembly completed in $t_assembly s")

    # 5. Solve
    println("[4/4] Solving System...")
    V = getExcitationVector(geosInfo, size(Zmat, 1), source)
    
    t_solve = @elapsed begin
        ICoeff, ch = solve(Zmat, V; solverT = solverT, rtol = rtol, restart = restart)
    end
    println("      Solved in $t_solve s")
    
    println("Legacy Benchmark Completed.")
end

run_legacy_benchmark()
